const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-110.517217, 45.506013]);
  const region = point.buffer(3000); // 3km buffer
  const scale = 500; // MODIS resolution

  // Define day ranges for mid-August and mid-September 2012 (2012 is leap year)
  const augustStart = 223; // August 10
  const augustEnd = 233;   // August 20
  const septemberStart = 254; // September 10
  const septemberEnd = 264;   // September 20

  // Helper function to get burned pixel count for a given month and day range
  function getBurnedCount(startDate, endDate, dayStart, dayEnd) {
    // Get the monthly image collection
    const col = ee.ImageCollection('MODIS/006/MCD64A1')
                  .filterDate(startDate, endDate);
    const size = col.size().getInfo();
    console.log(`${startDate} Images: ${size}`);
    if (size === 0) {
      return null; // Indicate no image
    }
    const image = col.first();
    // Create mask for burned pixels within the day range
    const burned = image.select('BurnDate')
                       .gte(dayStart)
                       .and(image.select('BurnDate').lte(dayEnd))
                       .rename('burned');
    // Count burned pixels in the region
    const result = burned.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    }).get('burned');
    const count = result.getInfo();
    // Also get total number of pixels in the region to check if image has data
    const totalPixels = image.select('BurnDate').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    }).get('BurnDate').getInfo();
    console.log(`Valid pixels in region: ${totalPixels}, Burned pixels: ${count}`);
    if (totalPixels === 0) {
      return -1; // Indicate no valid pixels (image doesn't cover region)
    }
    return count;
  }

  // 2. Data Acquisition & Processing
  const augCount = getBurnedCount('2012-08-01', '2012-08-31', augustStart, augustEnd);
  const sepCount = getBurnedCount('2012-09-01', '2012-09-30', septemberStart, septemberEnd);

  // 3. Check for data issues
  if (augCount === null || sepCount === null) {
    console.log("<answer>C1</answer>");
    return;
  }
  if (augCount === -1 || sepCount === -1) {
    console.log("<answer>C2</answer>");
    return;
  }
  if (augCount === undefined || sepCount === undefined || 
      isNaN(augCount) || isNaN(sepCount)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Output stats and determine answer
  console.log(`August 2012 burned pixels: ${augCount}`);
  console.log(`September 2012 burned pixels: ${sepCount}`);

  if (sepCount > augCount) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
